+
+  const panel = page.locator(".state-panel");
+  await expect(
+    panel.getByRole("heading", { name: "앱이 등록되었습니다" }),
+  ).toBeVisible();
+  await expect(
+    panel.getByText("현재 상태: 초안", { exact: true }),
