+  await expect(panel).not.toContainText(/즉시 게시|승인 Workflow|보안 심의/);
+  await panel.getByRole("button", { name: "내 앱으로 이동" }).click();
+  await expect(page).toHaveURL("/my/apps");
+  await expect(
+    page.getByRole("heading", { name: "내가 등록한 앱" }),
+  ).toBeVisible();
+});
