    expect(
      screen.queryByRole("heading", { name: "앱을 찾을 수 없습니다" }),
    ).toBeNull();
  });

  it("still reports a real transport failure as an error, not as a missing app", async () => {
    renderEdit(
      () =>
        new Response(
          JSON.stringify({
            code: "internal",
